// Enrich and format Prometheus / Alertmanager alerts per 14_workflow_engine.md §4.1
const items = $input.all();
const output = [];

for (const item of items) {
  const payload = item.json;
  const alerts = payload.alerts || [payload];

  for (const alert of alerts) {
    const status = alert.status || 'firing';
    const severity = (alert.labels && alert.labels.severity) || 'info';
    const alertName = (alert.labels && alert.labels.alertname) || 'Unknown Alert';
    const summary = (alert.annotations && alert.annotations.summary) || 'No summary provided';
    const description = (alert.annotations && alert.annotations.description) || '';
    const runbookUrl = (alert.annotations && alert.annotations.runbook_url) || '';

    let color = '#36a64f'; // green for resolved
    let emoji = '✅';

    if (status === 'firing') {
      switch (severity.toLowerCase()) {
        case 'critical':
          color = '#ff0000';
          emoji = '🚨';
          break;
        case 'high':
          color = '#ff9900';
          emoji = '⚠️';
          break;
        case 'medium':
          color = '#ffcc00';
          emoji = '⚡';
          break;
        default:
          color = '#439FE0';
          emoji = 'ℹ️';
      }
    }

    output.push({
      json: {
        status,
        severity,
        alertName,
        summary,
        description,
        runbookUrl,
        color,
        emoji,
        slackMessage: {
          text: `${emoji} *[${status.toUpperCase()}] ${alertName} (${severity.toUpperCase()})*\n*Summary:* ${summary}\n*Details:* ${description}${runbookUrl ? `\n*Runbook:* <${runbookUrl}|View Runbook>` : ''}`,
          attachments: [
            {
              color: color,
              fields: [
                { title: 'Severity', value: severity.toUpperCase(), short: true },
                { title: 'Status', value: status.toUpperCase(), short: true },
                { title: 'Module', value: (alert.labels && alert.labels.module) || 'platform', short: true }
              ],
              footer: 'Financial Tracker Platform Alert Router (n8n Sanctioned Workflow)',
              ts: Math.floor(Date.now() / 1000)
            }
          ]
        }
      }
    });
  }
}

return output;
